service.method:

DELETE 
  FROM #DB_OWNER#SGRID
 WHERE GRID_ID    = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND HOUSE_CODE = ${session.HOUSE_CODE}


SELECT COUNT(*) 
  FROM SGRID 
 WHERE GRID_ID    = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND HOUSE_CODE = ${session.HOUSE_CODE}

UPDATE #DB_OWNER#SGRID SET COL_TYPE = ${COL_TYPE}, COL_FORMAT = ${COL_FORMAT}, COL_MAX_LEN = ${COL_MAX_LEN}, COL_ALIGN = ${COL_ALIGN}, COL_VISIBLE = ${COL_VISIBLE}, SELECTED_YN = ${SELECTED_YN}, COL_SEQ = #{COL_SEQ}, TEXT_STYLE = ${TEXT_STYLE}, COL_COLOR = ${COL_COLOR}, COL_COMBO = ${COL_COMBO}, COL_SORT = ${COL_SORT}, CHANGE_USER_ID = ${session.ID}, CHANGE_DATE = ${current.DATE}, CHANGE_TIME = ${current.TIME}, NOT_NULL = ${NOT_NULL}, TEMPLATE = ${TEMPLATE} WHERE 1=1
AND GRID_ID = ${GRID_ID}
AND CODE = ${CODE} AND HOUSE_CODE = ${session.HOUSE_CODE}


SELECT COUNT(*) 
  FROM SLANG 
 WHERE SCREEN_ID  = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND LANGUAGE   = ${LANGUAGE}
   AND HOUSE_CODE = ${session.HOUSE_CODE}


	UPDATE #DB_OWNER#SLANG 
       SET CONTENTS    = ${CONTENTS}
		 , GRID_WIDTH  = ${COL_WIDTH}
		 , CHANGE_DATE = ${current.DATE}
		 , CHANGE_TIME = ${current.TIME}
     WHERE SCREEN_ID  = ${GRID_ID}
       AND CODE       = ${CODE}
       AND HOUSE_CODE = ${session.HOUSE_CODE}
       AND LANGUAGE   = ${LANGUAGE}
